            .bind(replacement.and_then(|event| event.location.as_deref()))
            .bind(replacement.map(|event| event.status.as_str()))
            .bind(
                replacement_timing
                    .as_ref()
                    .and_then(|timing| timing.timed_start_utc),
            )
            .bind(
                replacement_timing
                    .as_ref()
                    .and_then(|timing| timing.timed_end_utc),
            )
            .bind(
                replacement_timing
                    .as_ref()
                    .and_then(|timing| timing.timezone),
            )
            .bind(
                replacement_timing
                    .as_ref()
                    .and_then(|timing| timing.all_day_start_date),
            )
            .bind(
                replacement_timing
                    .as_ref()
                    .and_then(|timing| timing.all_day_end_date),
            )
            .bind(actor_user_id)
            .bind(now)
            .bind(now)
            .execute(&mut *transaction)
            .await?;
            exception_count += 1;
